@interface DylixLinuxEditor : UIViewController
@property NSString *session,*path,*root,*contentHash;
@property UITextView *text;
@property NSDictionary *file;
@property TFAIToolbox *toolbox;
@property TFAIRuntimePolicy *policy;
@property(weak) UIViewController *reviewHost;
@end
@implementation DylixLinuxEditor
- (void)viewDidLoad{[super viewDidLoad];self.title=self.path.lastPathComponent;self.view.backgroundColor=UIColor.systemBackgroundColor;self.text=[[UITextView alloc]initWithFrame:self.view.bounds];self.text.autoresizingMask=UIViewAutoresizingFlexibleWidth|UIViewAutoresizingFlexibleHeight;self.text.font=[UIFont monospacedSystemFontOfSize:14 weight:UIFontWeightRegular];self.text.text=self.file[@"content"];self.text.textContainerInset=UIEdgeInsetsMake(16,12,16,12);self.contentHash=self.file[@"sha256"];[self.view addSubview:self.text];self.navigationItem.rightBarButtonItems=@[AIBar(@"checkmark",@"保存到 Linux",self,@selector(save)),AIBar(@"square.and.arrow.up",@"写回项目",self,@selector(writeback))];self.navigationItem.rightBarButtonItems.lastObject.enabled=self.root.length>0;}
- (void)save{self.navigationItem.rightBarButtonItems.firstObject.enabled=NO;[TFAIISHRuntime.shared fileOperation:@"write" path:self.path arguments:@{@"content":self.text.text,@"sha256":self.contentHash} session:self.session completion:^(NSDictionary *r,NSError *e){self.navigationItem.rightBarButtonItems.firstObject.enabled=YES;if(e)AIAlert(self,@"未保存",e.localizedDescription);else{self.contentHash=r[@"sha256"];self.file=r;AIAlert(self,@"已保存到 Linux",@"项目文件未变化。需要写回项目时请使用右上角写回按钮。 ");}}];}
- (void)writeback{UIAlertController *a=[UIAlertController alertControllerWithTitle:@"写回当前项目" message:@"输入项目内的相对路径；下一步审核实际差异。仅支持 UTF-8 文件，父目录须已存在。" preferredStyle:UIAlertControllerStyleAlert];[a addTextFieldWithConfigurationHandler:^(UITextField *f){f.text=self.path.lastPathComponent;f.autocapitalizationType=UITextAutocapitalizationTypeNone;}];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"预览差异" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){[self prepareWriteback:a.textFields.firstObject.text content:self.text.text];}]];[self presentViewController:a animated:YES completion:nil];}
- (void)prepareWriteback:(NSString *)relative content:(NSString *)content{
 if(!self.root.length)return;NSError *error=nil;NSString *full=TFAISafePath(self.root,relative,NO,&error);if(!full){AIAlert(self,@"路径无效",error.localizedDescription);return;}NSString *project=TFAIDigest([self.root dataUsingEncoding:NSUTF8StringEncoding]);if(!self.toolbox){self.toolbox=[[TFAIToolbox alloc]initWithRoot:self.root projectID:project sessionID:self.session];self.policy=[[TFAIRuntimePolicy alloc]initWithRoot:self.root projectID:project sessionID:self.session];}
 // Let the toolbox validate the exact original, content limit, symlinks, Git lease and backups.
 BOOL exists=[NSFileManager.defaultManager fileExistsAtPath:full];NSDictionary *args;NSString *name;
 if(exists){NSDictionary *attr=[NSFileManager.defaultManager attributesOfItemAtPath:full error:nil];if([attr[NSFileSize] unsignedLongLongValue]>256*1024){AIAlert(self,@"无法生成差异",@"项目目标文件超过 256 KiB");return;}NSString *before=[NSString stringWithContentsOfFile:full encoding:NSUTF8StringEncoding error:&error];if(!before.length){AIAlert(self,@"无法生成差异",error.localizedDescription?:@"目标为空文件，请使用项目编辑器处理");return;}if([before isEqual:content]){AIAlert(self,@"内容相同",@"没有需要写回的差异");return;}name=@"propose_patch";args=@{@"edits":@[@{@"path":relative,@"before":before,@"after":content}]};}
 else{name=@"create_file";args=@{@"path":relative,@"content":content};}
 NSDictionary *request=@{@"id":NSUUID.UUID.UUIDString,@"name":name,@"arguments":args};[self.toolbox prepare:request completion:^(NSDictionary *plan,NSError *e){if(e){AIAlert(self,@"写回未准备",e.localizedDescription);return;}if([name isEqual:@"create_file"]){[self review:plan];return;}[self.toolbox execute:plan approved:YES completion:^(NSDictionary *r,NSError *e){if(e){AIAlert(self,@"差异未准备",e.localizedDescription);return;}[self.toolbox prepare:@{@"id":NSUUID.UUID.UUIDString,@"name":@"apply_approved_patch",@"arguments":@{@"proposal_id":r[@"proposal_id"]}} completion:^(NSDictionary *p,NSError *e){if(e)AIAlert(self,@"差异未准备",e.localizedDescription);else[self review:p];}];}];}];
}
- (void)review:(NSDictionary *)plan{if([[self.policy decisionForPlan:plan][@"decision"] isEqual:@"denied"]){AIAlert((self.reviewHost?:self),@"写回被拒绝",[self.policy decisionForPlan:plan][@"reason"]);return;}UIViewController *review=TFAIApprovalController(plan,^(BOOL approved,NSArray *indexes){[(self.reviewHost?:self) dismissViewControllerAnimated:YES completion:^{if(!approved)return;void(^apply)(NSDictionary *)=^(NSDictionary *p){NSError *e=nil;NSDictionary *decision=[self.policy decisionForPlan:p];if([decision[@"decision"] isEqual:@"denied"]){AIAlert((self.reviewHost?:self),@"未写回",decision[@"reason"]);return;}if(![decision[@"separateConfirmation"] boolValue]&&(![self.policy grantReviewedPlan:p session:self.session error:&e]||![self.policy consumeReviewedPlan:p error:&e])){AIAlert((self.reviewHost?:self),@"未写回",e.localizedDescription);return;}[self.toolbox setApprovalContext:@"explicit-preview"];[self.toolbox execute:p approved:YES completion:^(NSDictionary *r,NSError *e){if(e)AIAlert((self.reviewHost?:self),@"写回未完成",e.localizedDescription);else{UIAlertController *done=[UIAlertController alertControllerWithTitle:@"已写回项目" message:@"已按现有流程校验并保存，可撤销本次写回。" preferredStyle:UIAlertControllerStyleAlert];[done addAction:[UIAlertAction actionWithTitle:@"完成" style:UIAlertActionStyleCancel handler:nil]];[done addAction:[UIAlertAction actionWithTitle:@"撤销本次写回" style:UIAlertActionStyleDefault handler:^(UIAlertAction *a){[self.toolbox undo:^(NSDictionary *r,NSError *e){AIAlert((self.reviewHost?:self),e?@"撤销失败":@"已撤销",e.localizedDescription?:@"已恢复本次写回之前的项目文件");}];}]];[(self.reviewHost?:self) presentViewController:done animated:YES completion:nil];}}];};if(indexes)[self.toolbox selectEdits:indexes plan:plan completion:^(NSDictionary *p,NSError *e){if(e)AIAlert((self.reviewHost?:self),@"未写回",e.localizedDescription);else apply(p);}];else apply(plan);}];});[(self.reviewHost?:self) presentViewController:[[UINavigationController alloc]initWithRootViewController:review] animated:YES completion:nil];}
@end
@interface DylixLinuxFiles : UITableViewController <UIDocumentPickerDelegate>
@property NSString *session,*path,*root;
@property NSArray *items;
@property NSString *status;
@property NSArray *directoryFiles;
@property DylixLinuxEditor *reviewer;
@property BOOL busy;
@end
@implementation DylixLinuxFiles
- (void)viewDidLoad{[super viewDidLoad];self.title=[self.path isEqual:@"/"]?@"Linux 文件":self.path.lastPathComponent;self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=64;self.tableView.allowsMultipleSelectionDuringEditing=YES;self.navigationItem.leftItemsSupplementBackButton=YES;self.navigationItem.leftBarButtonItem=AIBar(@"arrow.up",@"上一级目录",self,@selector(parent));self.navigationItem.rightBarButtonItems=@[AIBar(@"arrow.clockwise",@"刷新",self,@selector(reload)),AIBar(@"plus",@"新建与导入",self,@selector(add))];[self reload];}
- (void)parent{if(self.busy||[self.path isEqual:@"/"])return;self.path=self.path.stringByDeletingLastPathComponent;if(!self.path.length)self.path=@"/";self.title=[self.path isEqual:@"/"]?@"Linux 文件":self.path.lastPathComponent;[self reload];}
- (void)reload{if(self.busy)return;self.busy=YES;self.status=@"正在读取 Linux 目录…";[self.tableView reloadData];[TFAIISHRuntime.shared fileOperation:@"list" path:self.path arguments:@{} session:self.session completion:^(NSDictionary *r,NSError *e){self.busy=NO;self.items=r[@"items"]?:@[];self.status=e.localizedDescription?:[NSString stringWithFormat:@"%@ · %lu 项%@",self.path,(unsigned long)self.items.count,[r[@"truncated"] boolValue]?@"（已截断，请缩小目录）":@""];[self.tableView reloadData];}];}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return self.items.count;}
- (NSString *)tableView:(UITableView *)t titleForFooterInSection:(NSInteger)s{return self.status.length?self.status:@"此目录为空";}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)i{NSDictionary *r=self.items[i.row];BOOL dir=[r[@"kind"] isEqual:@"directory"],file=[r[@"kind"] isEqual:@"file"];UITableViewCell *c=AICell(r[@"name"],dir?@"目录":file?[NSByteCountFormatter stringFromByteCount:[r[@"bytes"] longLongValue] countStyle:NSByteCountFormatterCountStyleFile]:@"链接或设备，不跟随",dir?@"folder":file?@"doc":@"link");c.accessoryType=dir?UITableViewCellAccessoryDisclosureIndicator:UITableViewCellAccessoryNone;c.selectionStyle=(dir||file)?UITableViewCellSelectionStyleDefault:UITableViewCellSelectionStyleNone;return c;}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)i{if(self.tableView.editing)return;[t deselectRowAtIndexPath:i animated:YES];NSDictionary *r=self.items[i.row];if([r[@"kind"] isEqual:@"directory"]){DylixLinuxFiles *p=[[DylixLinuxFiles alloc]initWithStyle:UITableViewStyleInsetGrouped];p.session=self.session;p.root=self.root;p.path=r[@"path"];[self.navigationController pushViewController:p animated:YES];return;}if(![r[@"kind"] isEqual:@"file"])return;UIAlertController *a=[UIAlertController alertControllerWithTitle:r[@"name"] message:nil preferredStyle:UIAlertControllerStyleActionSheet];[a addAction:[UIAlertAction actionWithTitle:@"打开 UTF-8 文本" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){[TFAIISHRuntime.shared fileOperation:@"read" path:r[@"path"] arguments:@{} session:self.session completion:^(NSDictionary *file,NSError *e){if(e)AIAlert(self,@"无法打开",e.localizedDescription);else{DylixLinuxEditor *p=[DylixLinuxEditor new];p.session=self.session;p.root=self.root;p.path=r[@"path"];p.file=file;[self.navigationController pushViewController:p animated:YES];}}];}]];[a addAction:[UIAlertAction actionWithTitle:@"导出与分享" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){[TFAIISHRuntime.shared exportFile:r[@"path"] session:self.session completion:^(NSDictionary *out,NSError *e){NSURL *url=out?TFAIISHExportURL(out,self.session):nil;if(!url){AIAlert(self,@"导出失败",e.localizedDescription?:@"导出副本无效");return;}UIActivityViewController *share=[[UIActivityViewController alloc]initWithActivityItems:@[url] applicationActivities:nil];share.popoverPresentationController.sourceView=self.view;share.popoverPresentationController.sourceRect=CGRectMake(CGRectGetMidX(self.view.bounds),CGRectGetMidY(self.view.bounds),1,1);[self presentViewController:share animated:YES completion:nil];}];}]];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.sourceView=[t cellForRowAtIndexPath:i];a.popoverPresentationController.sourceRect=[t cellForRowAtIndexPath:i].bounds;[self presentViewController:a animated:YES completion:nil];}
- (void)add{UIAlertController *a=[UIAlertController alertControllerWithTitle:@"新建与导入" message:@"导入副本进入 /workspace/imports，不修改原文件。" preferredStyle:UIAlertControllerStyleActionSheet];[a addAction:[UIAlertAction actionWithTitle:@"选择多项 / 复制 / 移动" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){[self selectFiles];}]];[a addAction:[UIAlertAction actionWithTitle:@"搜索此目录及子目录" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){[self searchFiles];}]];if(self.root.length)[a addAction:[UIAlertAction actionWithTitle:@"审核目录并写回项目" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){[self reviewDirectory];}]];for(NSString *kind in @[@"目录",@"文本文件"])[a addAction:[UIAlertAction actionWithTitle:[@"新建" stringByAppendingString:kind] style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){UIAlertController *p=[UIAlertController alertControllerWithTitle:[@"新建" stringByAppendingString:kind] message:nil preferredStyle:UIAlertControllerStyleAlert];[p addTextFieldWithConfigurationHandler:nil];[p addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[p addAction:[UIAlertAction actionWithTitle:@"创建" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){NSString *name=p.textFields.firstObject.text;if(!name.length||![name isEqual:name.lastPathComponent]||[name isEqual:@"."]||[name isEqual:@".."])return;[TFAIISHRuntime.shared fileOperation:[kind isEqual:@"目录"]?@"mkdir":@"write" path:[self.path stringByAppendingPathComponent:name] arguments:@{@"content":@"",@"sha256":@"missing"} session:self.session completion:^(NSDictionary *r,NSError *e){if(e)AIAlert(self,@"未创建",e.localizedDescription);else[self reload];}];}]];[self presentViewController:p animated:YES completion:nil];}]];[a addAction:[UIAlertAction actionWithTitle:@"导入文件副本" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){UIDocumentPickerViewController *p=[[UIDocumentPickerViewController alloc]initForOpeningContentTypes:@[UTTypeData] asCopy:YES];p.delegate=self;[self presentViewController:p animated:YES completion:nil];}]];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.barButtonItem=self.navigationItem.rightBarButtonItems.lastObject;[self presentViewController:a animated:YES completion:nil];}

- (void)selectFiles{[self.tableView setEditing:YES animated:YES];self.navigationItem.rightBarButtonItems=@[AIBar(@"checkmark",@"完成选择",self,@selector(finishSelection)),AIBar(@"folder.badge.plus",@"操作所选文件",self,@selector(batchMenu))];}
- (void)finishSelection{[self.tableView setEditing:NO animated:YES];self.navigationItem.rightBarButtonItems=@[AIBar(@"arrow.clockwise",@"刷新",self,@selector(reload)),AIBar(@"plus",@"新建与导入",self,@selector(add))];}
- (void)batchMenu{NSArray *selected=self.tableView.indexPathsForSelectedRows;if(!selected.count){AIAlert(self,@"尚未选择",@"点选需要处理的文件或目录");return;}NSMutableArray *paths=[NSMutableArray new];for(NSIndexPath *i in selected)if(i.row<self.items.count)[paths addObject:self.items[i.row][@"path"]];UIAlertController *a=[UIAlertController alertControllerWithTitle:[NSString stringWithFormat:@"已选 %lu 项",(unsigned long)paths.count] message:@"仅操作当前 Linux 副本；目标已存在时整批停止，不覆盖。" preferredStyle:UIAlertControllerStyleActionSheet];for(NSString *op in @[@"copy",@"move",@"rename"]){if([op isEqual:@"rename"]&&paths.count!=1)continue;NSString *title=[op isEqual:@"copy"]?@"复制到目录":[op isEqual:@"move"]?@"移动到目录":@"重命名";[a addAction:[UIAlertAction actionWithTitle:title style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){UIAlertController *p=[UIAlertController alertControllerWithTitle:title message:[op isEqual:@"rename"]?@"输入新名称":@"输入 /workspace 内目标目录的完整路径" preferredStyle:UIAlertControllerStyleAlert];[p addTextFieldWithConfigurationHandler:^(UITextField *f){f.text=[op isEqual:@"rename"]?[paths.firstObject lastPathComponent]:@"/workspace";f.autocapitalizationType=UITextAutocapitalizationTypeNone;f.autocorrectionType=UITextAutocorrectionTypeNo;}];[p addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[p addAction:[UIAlertAction actionWithTitle:@"确认操作" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){NSString *dest=p.textFields.firstObject.text;if([op isEqual:@"rename"]){if(!dest.length||![dest isEqual:dest.lastPathComponent]||[dest isEqual:@"."]||[dest isEqual:@".."])return;dest=[[paths.firstObject stringByDeletingLastPathComponent] stringByAppendingPathComponent:dest];}self.busy=YES;[TFAIISHRuntime.shared fileOperation:op path:[op isEqual:@"rename"]?paths.firstObject:self.path arguments:@{@"paths":paths,@"destination":dest?:@""} session:self.session completion:^(NSDictionary *r,NSError *e){self.busy=NO;[self finishSelection];if(e)AIAlert(self,@"操作未完成",e.localizedDescription);[self reload];}];}]];[self presentViewController:p animated:YES completion:nil];}]];}[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.barButtonItem=self.navigationItem.rightBarButtonItems.lastObject;[self presentViewController:a animated:YES completion:nil];}
- (void)searchFiles{UIAlertController *a=[UIAlertController alertControllerWithTitle:@"搜索文件名与路径" message:@"搜索当前目录及子目录，不跟随链接；最多 1000 项、24 层。" preferredStyle:UIAlertControllerStyleAlert];[a addTextFieldWithConfigurationHandler:nil];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"搜索" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){self.busy=YES;[TFAIISHRuntime.shared fileOperation:@"search" path:self.path arguments:@{@"query":a.textFields.firstObject.text?:@""} session:self.session completion:^(NSDictionary *r,NSError *e){self.busy=NO;if(e){AIAlert(self,@"搜索未完成",e.localizedDescription);return;}self.items=r[@"items"];self.status=[NSString stringWithFormat:@"搜索结果 %lu 项%@；刷新返回原目录",(unsigned long)self.items.count,[r[@"truncated"] boolValue]?@"（已截断）":@""];[self.tableView reloadData];}];}]];[self presentViewController:a animated:YES completion:nil];}
- (void)reviewDirectory{self.busy=YES;[TFAIISHRuntime.shared fileOperation:@"tree" path:self.path arguments:@{} session:self.session completion:^(NSDictionary *r,NSError *e){self.busy=NO;if(e){AIAlert(self,@"无法审核目录",e.localizedDescription);return;}self.directoryFiles=r[@"items"];UIAlertController *a=[UIAlertController alertControllerWithTitle:@"目录写回审核" message:[NSString stringWithFormat:@"可审核 %lu 个 UTF-8 文件，跳过 %lu 项（二进制、过大或超限）。逐文件核对差异并沿用项目审批；不会删除项目文件。目标父目录须已存在；输入项目内目标目录，留空表示项目根目录。",(unsigned long)self.directoryFiles.count,(unsigned long)[r[@"skipped"] count]] preferredStyle:UIAlertControllerStyleAlert];[a addTextFieldWithConfigurationHandler:^(UITextField *f){f.placeholder=@"项目内相对目录";f.autocapitalizationType=UITextAutocapitalizationTypeNone;}];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"查看文件差异" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){NSString *destination=a.textFields.firstObject.text?:@"";self.reviewer=[DylixLinuxEditor new];self.reviewer.root=self.root;self.reviewer.session=self.session;self.reviewer.reviewHost=self;NSString *project=TFAIDigest([self.root dataUsingEncoding:NSUTF8StringEncoding]);self.reviewer.toolbox=[[TFAIToolbox alloc]initWithRoot:self.root projectID:project sessionID:self.session];self.reviewer.policy=[[TFAIRuntimePolicy alloc]initWithRoot:self.root projectID:project sessionID:self.session];[self.reviewer.toolbox prepareImportedTexts:self.directoryFiles destination:destination completion:^(NSDictionary *plan,NSError *error){if(!plan){AIAlert(self,@"目录未准备写回",error.localizedDescription);return;}[self.reviewer review:plan];}]; }]];[self presentViewController:a animated:YES completion:nil];}];}
- (void)documentPicker:(UIDocumentPickerViewController *)p didPickDocumentsAtURLs:(NSArray<NSURL *> *)urls{NSURL *url=urls.firstObject;BOOL access=[url startAccessingSecurityScopedResource];[TFAIISHRuntime.shared importFile:url name:url.lastPathComponent session:self.session completion:^(NSDictionary *r,NSError *e){if(access)[url stopAccessingSecurityScopedResource];if(e)AIAlert(self,@"导入失败",e.localizedDescription);else{self.path=@"/workspace/imports";[self reload];}}];}
@end
UIViewController *TFAIISHFilesController(NSString *session,NSString *root){DylixLinuxFiles *p=[[DylixLinuxFiles alloc]initWithStyle:UITableViewStyleInsetGrouped];p.session=session;p.root=root;p.path=@"/workspace";return p;}
